{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01Jx5UGHyq2DdW4vjP1sB5q3","type":"tool_result","content":"95\t    )\n96\t\n97\t\n98\tdef mi_compute(halstead_volume, complexity, sloc, comments):\n99\t    '''Compute the Maintainability Index (MI) given the Halstead Volume, the\n100\t    Cyclomatic Complexity, the SLOC number and the number of comment lines.\n101\t    Usually it is not used directly but instead :func:`~radon.metrics.mi_visit`\n102\t    is preferred.\n103\t    '''\n104\t    if any(metric <= 0 for metric in (halstead_volume, sloc)):\n105\t        return 100.0\n106\t    sloc_scale = math.log(sloc)\n107\t    volume_scale = math.log(halstead_volume)\n108\t    comments_scale = math.sqrt(2.46 * math.radians(comments))\n109\t    # Non-normalized MI\n110\t    nn_mi = (\n111\t        171\n112\t        - 5.2 * volume_scale\n113\t        - 0.23 * complexity\n114\t        - 16.2 * sloc_scale\n115\t        + 50 * math.sin(comments_scale)\n116\t    )\n117\t    return min(max(0.0, nn_mi * 100 / 171.0), 100.0)\n118\t\n119\t\n120\tdef mi_parameters(code, count_multi=True):\n121\t    '''Given a source code snippet, compute the necessary parameters to\n122\t    compute the Maintainability Index metric. These include:\n123\t\n124\t        * the Halstead Volume\n125\t        * the Cyclomatic Complexity\n126\t        * the number of LLOC (Logical Lines of Code)\n127\t        * the percent of lines of comment\n128\t\n129\t    :param multi: If True, then count multiline strings as comment lines as\n130\t        well. This is not always safe because Python multiline strings are not\n131\t        always docstrings.\n132\t    '''\n133\t    ast_node = ast.parse(code)\n134\t    raw = analyze(code)\n135\t    comments_lines = raw.comments + (raw.multi if count_multi else 0)\n136\t    comments = comments_lines / float(raw.sloc) * 100 if raw.sloc != 0 else 0\n137\t    return (\n138\t        h_visit_ast(ast_node).total.volume,\n139\t        ComplexityVisitor.from_ast(ast_node).total_complexity,\n140\t        raw.lloc,\n141\t        comments,\n142\t    )\n143\t\n144\t\n145\tdef mi_visit(code, multi):\n146\t    '''Visit the code and compute the Maintainability Index (MI) from it.'''\n147\t    return mi_compute(*mi_parameters(code, multi))\n148\t\n149\t\n150\tdef mi_rank(score):\n151\t    r'''Rank the score with a letter:\n152\t\n153\t        * A if :math:`\\text{score} > 19`;\n154\t        * B if :math:`9 < \\text{score} \\le 19`;"}]},"parent_tool_use_id":null,"session_id":"c021025c-a35d-40bb-b4a0-776f88c70a09","uuid":"dba1d33f-2f4d-4038-820d-d24f1d2f5e88","timestamp":"2026-11-07T14:32:10.295Z","tool_use_result":{"type":"text","file":{"filePath":"/home/user/earshot_d2/ws/workspace/radon/metrics.py","content":"    )\n\n\ndef mi_compute(halstead_volume, complexity, sloc, comments):\n    '''Compute the Maintainability Index (MI) given the Halstead Volume, the\n    Cyclomatic Complexity, the SLOC number and the number of comment lines.\n    Usually it is not used directly but instead :func:`~radon.metrics.mi_visit`\n    is preferred.\n    '''\n    if any(metric <= 0 for metric in (halstead_volume, sloc)):\n        return 100.0\n    sloc_scale = math.log(sloc)\n    volume_scale = math.log(halstead_volume)\n    comments_scale = math.sqrt(2.46 * math.radians(comments))\n    # Non-normalized MI\n    nn_mi = (\n        171\n        - 5.2 * volume_scale\n        - 0.23 * complexity\n        - 16.2 * sloc_scale\n        + 50 * math.sin(comments_scale)\n    )\n    return min(max(0.0, nn_mi * 100 / 171.0), 100.0)\n\n\ndef mi_parameters(code, count_multi=True):\n    '''Given a source code snippet, compute the necessary parameters to\n    compute the Maintainability Index metric. These include:\n\n        * the Halstead Volume\n        * the Cyclomatic Complexity\n        * the number of LLOC (Logical Lines of Code)\n        * the percent of lines of comment\n\n    :param multi: If True, then count multiline strings as comment lines as\n        well. This is not always safe because Python multiline strings are not\n        always docstrings.\n    '''\n    ast_node = ast.parse(code)\n    raw = analyze(code)\n    comments_lines = raw.comments + (raw.multi if count_multi else 0)\n    comments = comments_lines / float(raw.sloc) * 100 if raw.sloc != 0 else 0\n    return (\n        h_visit_ast(ast_node).total.volume,\n        ComplexityVisitor.from_ast(ast_node).total_complexity,\n        raw.lloc,\n        comments,\n    )\n\n\ndef mi_visit(code, multi):\n    '''Visit the code and compute the Maintainability Index (MI) from it.'''\n    return mi_compute(*mi_parameters(code, multi))\n\n\ndef mi_rank(score):\n    r'''Rank the score with a letter:\n\n        * A if :math:`\\text{score} > 19`;\n        * B if :math:`9 < \\text{score} \\le 19`;","numLines":60,"startLine":95,"totalLines":158}},"tool_result_meta":[{"id":"toolu_01Jx5UGHyq2DdW4vjP1sB5q3","permission_decision":{"decision":"accept","source":"config","reason_type":"mode"}}]}
